-- Fee holds (docs/designs/fee-holds): HOLD/RELEASE events per plan due; a held due stays owed but is not collected; held and
-- collectable defined once in fee_due_balance; the allocation guard refuses a held due. Head generated by prisma migrate diff.
-- CreateTable
CREATE TABLE "app"."fee_hold_event" (
    "id" BIGSERIAL NOT NULL,
    "due_id" BIGINT NOT NULL,
    "centre_id" INTEGER NOT NULL,
    "action" TEXT NOT NULL,
    "reason" TEXT NOT NULL,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "created_by" UUID NOT NULL,

    CONSTRAINT "fee_hold_event_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "fee_hold_event_due_id_id_idx" ON "app"."fee_hold_event"("due_id", "id");

-- AddForeignKey
ALTER TABLE "app"."fee_hold_event" ADD CONSTRAINT "fee_hold_event_due_id_fkey" FOREIGN KEY ("due_id") REFERENCES "app"."fee_due"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;

-- AddForeignKey
ALTER TABLE "app"."fee_hold_event" ADD CONSTRAINT "fee_hold_event_centre_id_fkey" FOREIGN KEY ("centre_id") REFERENCES "app"."centre"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;

-- AddForeignKey
ALTER TABLE "app"."fee_hold_event" ADD CONSTRAINT "fee_hold_event_created_by_fkey" FOREIGN KEY ("created_by") REFERENCES "app"."app_user"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;



-- ---------- Named checks ----------
alter table app.fee_hold_event add constraint fee_hold_event_action_check check (action in ('HOLD', 'RELEASE'));
alter table app.fee_hold_event add constraint fee_hold_event_reason_check check (reason = btrim(reason) and char_length(reason) between 1 and 500);

-- ---------- Held and collectable, defined once next to owed (Z1, D2, Z8-1): the latest event by id ----------
create or replace view app.fee_due_balance with (security_invoker = true) as
  select x.due_id, x.registration_id, x.paid, x.outstanding, x.owed,
    coalesce(x.held, false) as held,
    (case when coalesce(x.held, false) then 0 else x.owed end)::numeric(14,2) as collectable
  from (
    select d.id as due_id, d.registration_id,
      coalesce(sum(a.amount) filter (where r.status = 'ACTIVE'), 0)::numeric(14,2) as paid,
      (d.gross - coalesce(sum(a.amount) filter (where r.status = 'ACTIVE'), 0))::numeric(14,2) as outstanding,
      (case when d.source = 'PLAN' then d.gross - coalesce(sum(a.amount) filter (where r.status = 'ACTIVE'), 0) else 0 end)::numeric(14,2) as owed,
      (h.action = 'HOLD') as held
    from app.fee_due d
      left join app.receipt_allocation a on a.due_id = d.id
      left join app.receipt r on r.id = a.receipt_id
      left join lateral (select e.action from app.fee_hold_event e where e.due_id = d.id order by e.id desc limit 1) h on true
    group by d.id, h.action) x;

-- ---------- Guard: rules only; ids follow the lock order, so the latest event is the state (D1) ----------
create function app.fee_hold_guard() returns trigger
language plpgsql security invoker set search_path = pg_catalog, app
as $$
declare d_reg uuid; d_centre int; d_source text; b_owed numeric; b_held boolean;
begin
  select d.registration_id, d.centre_id, d.source into d_reg, d_centre, d_source from app.fee_due d where d.id = new.due_id;
  if not found then
    raise exception 'the due is not found: constraint "fee_hold_guard"' using errcode = '23514', constraint = 'fee_hold_guard';
  end if;
  perform pg_advisory_xact_lock(hashtext('fee-dues:' || d_reg::text));
  new.id := nextval('app.fee_hold_event_id_seq');
  new.created_at := now();
  new.created_by := coalesce(app.session_user_id(), new.created_by);
  if d_centre is distinct from new.centre_id or d_source is distinct from 'PLAN' then
    raise exception 'a hold is on a plan due of its centre: constraint "fee_hold_guard"' using errcode = '23514', constraint = 'fee_hold_guard';
  end if;
  select b.owed, b.held into b_owed, b_held from app.fee_due_balance b where b.due_id = new.due_id;
  if (new.action = 'HOLD') = coalesce(b_held, false) then
    raise exception 'a hold and a release alternate: constraint "fee_hold_state_guard"' using errcode = '23514', constraint = 'fee_hold_state_guard';
  end if;
  if new.action = 'HOLD' then
    if coalesce(b_owed, 0) <= 0 then
      raise exception 'a hold needs something owed: constraint "fee_hold_paid_guard"' using errcode = '23514', constraint = 'fee_hold_paid_guard';
    end if;
  end if;
  return new;
end $$;
create trigger fee_hold_guard before insert on app.fee_hold_event for each row execute function app.fee_hold_guard();
create trigger fee_hold_event_no_update_delete before update or delete on app.fee_hold_event for each row execute function app.ticket_immutable();
create trigger fee_hold_event_no_truncate before truncate on app.fee_hold_event for each statement execute function app.ticket_immutable();

-- ---------- Allocation guard: a held due is refused (0029's body plus the hold step) ----------
create or replace function app.receipt_allocation_guard() returns trigger
language plpgsql security invoker set search_path = pg_catalog, app
as $$
declare
  r_reg uuid; r_centre int; r_currency text; r_at timestamptz;
  d_reg uuid; d_centre int; d_currency text; d_type int; d_source text; d_at timestamptz;
  owed numeric; is_held boolean; rate numeric; hsn text;
  g_enabled boolean; g_supply text; g_in text; tax numeric;
begin
  select r.registration_id, r.centre_id, r.currency::text, r.created_at into r_reg, r_centre, r_currency, r_at
    from app.receipt r where r.id = new.receipt_id;
  if not found then
    raise exception 'the receipt is not found: constraint "receipt_allocation_guard"' using errcode = '23514', constraint = 'receipt_allocation_guard';
  end if;
  -- lines only in the receipt's own transaction (D15): now() is the transaction's start time
  if r_at is distinct from now() then
    raise exception 'lines are added only with their receipt: constraint "receipt_allocation_guard"' using errcode = '23514', constraint = 'receipt_allocation_guard';
  end if;
  perform pg_advisory_xact_lock(hashtext('fee-dues:' || r_reg::text));
  select d.registration_id, d.centre_id, d.currency::text, d.fee_type_id, d.source, d.created_at into d_reg, d_centre, d_currency, d_type, d_source, d_at
    from app.fee_due d where d.id = new.due_id;
  if not found or d_reg is distinct from r_reg or d_centre is distinct from r_centre or d_currency is distinct from r_currency
     or new.centre_id is distinct from r_centre then
    raise exception 'a line is a due of the receipt''s registration, in its currency: constraint "receipt_allocation_guard"' using errcode = '23514', constraint = 'receipt_allocation_guard';
  end if;
  -- an ad-hoc due is paid only in the transaction that made it: a void one is never paid later (adhoc-fees Z3, D2)
  if d_source = 'ADHOC' then
    if d_at is distinct from now() then
      raise exception 'an ad-hoc fee is paid with its own receipt: constraint "receipt_allocation_guard"' using errcode = '23514', constraint = 'receipt_allocation_guard';
    end if;
  end if;
  select b.outstanding, b.held into owed, is_held from app.fee_due_balance b where b.due_id = new.due_id;
  -- a held due is not collected (fee-holds D-FEE-5). Events are read as invoker; receipt and fee_hold_event share the
  -- student.view select policy, so a caller who could not see an event could not see the receipt either (D6)
  if found then
    if is_held then
      raise exception 'that due is on hold: constraint "receipt_hold_guard"' using errcode = '23514', constraint = 'receipt_hold_guard';
    end if;
  end if;
  if not found or new.amount > owed then
    raise exception 'a due is never paid beyond what is outstanding: constraint "receipt_over_guard"' using errcode = '23514', constraint = 'receipt_over_guard';
  end if;
  -- tax at receipt (DD-3): the fee type's rate and HSN/SAC; the centre's registration; GST in India only (INR)
  select t.gst_rate, t.hsn_sac into rate, hsn from app.fee_type t where t.id = d_type;
  if not found then
    raise exception 'the fee type is not found: constraint "receipt_tax_guard"' using errcode = '23514', constraint = 'receipt_tax_guard';
  end if;
  select c.gst_enabled, c.gst_supply, c.gstin into g_enabled, g_supply, g_in from app.centre c where c.id = r_centre;
  if not found then
    raise exception 'the centre is not found: constraint "receipt_tax_guard"' using errcode = '23514', constraint = 'receipt_tax_guard';
  end if;
  new.gst_rate := rate;
  new.hsn_sac := hsn;
  if g_enabled and r_currency = 'INR' then
    if g_supply is null or g_in is null then
      raise exception 'a GST-registered centre needs its supply and GSTIN: constraint "receipt_tax_guard"' using errcode = '23514', constraint = 'receipt_tax_guard';
    end if;
    new.taxable := round(new.amount * 100 / (100 + rate), 2);
    tax := new.amount - new.taxable;
    if g_supply = 'INTERSTATE' then
      new.cgst := 0; new.sgst := 0; new.igst := tax;
    else
      new.cgst := round(tax / 2, 2); new.sgst := tax - new.cgst; new.igst := 0;
    end if;
  else
    new.taxable := new.amount; new.cgst := 0; new.sgst := 0; new.igst := 0;
  end if;
  return new;
end $$;

-- ---------- RLS: student.view reads, fee.hold writes; never changed ----------
alter table app.fee_hold_event enable row level security;
alter table app.fee_hold_event force row level security;
create policy fee_hold_event_select on app.fee_hold_event for select using (centre_id = any ((select app.scoped_centre_ids('student.view'))::int[]));
create policy fee_hold_event_insert on app.fee_hold_event for insert with check (centre_id = any ((select app.scoped_centre_ids('fee.hold'))::int[]));
create policy fee_hold_event_update on app.fee_hold_event for update using (false);
create policy fee_hold_event_delete on app.fee_hold_event for delete using (false);

-- ---------- Permission ----------
insert into app.permission (key, description, sensitive) values ('fee.hold', 'Hold and release a learner''s fee dues', false)
on conflict (key) do nothing;
insert into app.role_permission (role_id, permission_key) select id, 'fee.hold' from app.role where key = 'system_admin'
on conflict do nothing;

-- ---------- Grants: id, who and when are the guard's ----------
grant select, insert (due_id, centre_id, action, reason) on app.fee_hold_event to gems_app;
grant usage on sequence app.fee_hold_event_id_seq to gems_app;
